$test=m09connection()->pdo();$testDb=(string)getenv('TEST_DB_DATABASE_M09');$identity=$test->query('SELECT DATABASE() db,CURRENT_USER() account,VERSION() engine')->fetch();App\Core\Persistence\IntegrationTestSafety::assertConnectionIdentity($testDb,(string)getenv('TEST_DB_USERNAME_M09'),$identity['db'],$identity['account']);m09check($identity['engine']===$snapshot['engine'],'Restore engine mismatch');$testStore=new App\Core\Persistence\MySqlMigrationStore($test);m09check($testStore->acquireLock('ayala_m09_isolated_integration',10),'Isolated database busy');
